/**
 * A failure that already carries a machine-readable code.
 *
 * This shape is what the plugin's own layers raise: the client sets a `code` off
 * the endpoint's answer, and the adapter sets one for its own refusals. The host
 * boundary translates it into the harness's error class, because that class
 * belongs to the host — naming it here would make this module unusable outside a
 * mounted harness, including in its own tests.
 */
export interface CodedError extends Error {
  /** Stable machine code, from the endpoint or from this plugin. */
  code: string
  /** HTTP status, when the failure was a response rather than a transport fault. */
  status?: number
  /** Whether the account's plan is what refused. */
  planUsage?: boolean
}

/**
 * Whether a thrown value already carries a usable code.
 *
 * A property check rather than `instanceof`: the harness may resolve a second
 * copy of this package, and an error thrown by one copy is not an instance of
 * the other's class.
 */
export function isCodedError(error: unknown): error is CodedError {
  return error instanceof Error && typeof (error as { code?: unknown }).code === 'string'
}

/** Build one coded error for a refusal this adapter makes itself. */
function coded(message: string, code: string): CodedError {
  const error = new Error(message) as CodedError
  error.code = code
  return error
}

/**
 * Whether a failure reads as a dropped connection rather than a decision.
 *
 * The wording is the built-in pi-ai adapter's, including undici's bare
 * `terminated` — what a mid-stream socket drop looks like once the real
 * SocketError has been flattened away — because a transient failure has to be
 * told apart from a refusal here: one is worth retrying, the other is not.
 *
 * @param message - the failure's text.
 * @returns whether it reads as transport.
 */
function isTransportFailure(message: string): boolean {
  return /\b(?:network|connection|socket|fetch)\b|\bECONN[A-Z]+\b|\bterminated\b|premature close/i.test(message)
    || /\btime(?:d)?\s*out\b|timeout/i.test(message)
    || /\b5\d\d\b/.test(message)
    || /\b429\b|rate.?limit/i.test(message)
}

/** How long a model listing is reused before the account is asked again. */
const LISTING_TTL_MS = 60_000

/** Longest hand-set display name accepted for one model. */
const MAX_MODEL_NAME_LENGTH = 200

/** What the adapter needs from the world around it. */
export interface ChatGptAdapterOptions {
  /** The credential owner this adapter asks for a usable grant. */
  auth: ChatGptAuth
  /** API base URL override (tests, gateways). */
  baseUrl?: string
  /** Display name for the provider row. */
  displayName?: string
  /**
   * Offer the models measured to work on this route that the account's listing
   * omits. Defaults to true: the listing demonstrably leaves out models this
   * route serves, and hiding them hides capability the account already has.
   */
  includeUnlisted?: boolean
  /** Explicit DSH context budget takes precedence over catalog metadata; absent uses model-ID defaults. */
  contextWindowLimit?: number | (() => number | undefined)
  /** Exact model IDs mapped to context budgets, taking precedence over the global budget. */
  modelContextWindowLimits?: Readonly<Record<string, number>> | (() => Readonly<Record<string, number>> | undefined)
  /** Maximum idle time waiting for a streaming SSE chunk, in ms. */
  streamIdleTimeoutMs?: number | (() => number | undefined)
  /** Clock, so the listing cache can be tested. */
  now?: () => number
  /**
   * Called when a listing succeeds after one or more failures.
   *
   * The harness's model selector caches its own catalog; when a provider failure
   * is cached, its in-menu Retry can re-read that cache instead of asking the
   * provider again. The plugin turns this callback into
   * `llm/adapters-updated`, so a roster that recovers replaces the stale failure
   * without a window reload.
   */
  onListingRecovered?: () => void
  /**
   * The installation's state directory, where the roster overrides record
   * (switches and display names) lives.
   *
   * Optional so tests that never touch overrides can omit it; the override
   * methods fail loudly when it is absent rather than pretending to remember
   * edits.
   */
  stateDir?: string
  /**
   * Called after a roster override is persisted.
   *
   * The selector rebuilds its catalog only when the Host says something changed,
   * so a toggle that hid or restored a model — or a rename it should display —
   * would otherwise not appear until a reload. The plugin turns this into
   * `llm/adapters-updated`, exactly as a roster change does.
   */
  onModelSwitchesChanged?: () => void
}

/** One model as the harness reads a listing. */
export interface HarnessModelInfo {
  provider: string
  id: string
  name: string
  inputModalities: readonly ('text' | 'image')[]
}

/** Everything the harness may know about one model. */
export interface HarnessResolvedModel extends HarnessModelInfo {
  context: { contextWindow: number }
  defaultMaxTokens?: number
  systemPromptUpdate?: 'in-history'
  reasoning?: {
    efforts: readonly { id: string, name: string, description?: string }[]
    defaultEffort?: string
  }
}

/** One request as the harness states it, reduced to what this adapter reads. */
export interface HarnessRequest {
  provider: string
  model: string
  messages: readonly HarnessMessage[]
  system?: string
  tools?: readonly { name: string, description: string, parameters: Record<string, unknown> }[]
  reasoningEffort?: string
  signal?: AbortSignal
  sessionId?: string
  purpose?: string
}

/** One message as the harness states it. */
export interface HarnessMessage {
  role: 'system' | 'developer' | 'user' | 'assistant' | 'tool'
  content: readonly HarnessBlock[]
  /** Present on a tool-role message: the call it answers. */
  toolCallId?: string
  isError?: boolean
  source?: unknown
}

/** One content block as the harness states it. */
export type HarnessBlock =
  | { type: 'text', text: string }
  | { type: 'reasoning', text: string }
  | { type: 'tool-call', id: string, name: string, arguments: string }
  | { type: string, [key: string]: unknown }

/** Preserve roles, blocks and tool results in the host's conversational order. */
export function toNeutralRequest(request: HarnessRequest, scope?: string): NeutralRequest {
  const context: ReplayContext | undefined = scope === undefined
    ? undefined : { provider: request.provider, model: request.model, scope }
  const messages: NeutralMessage[] = request.messages.map(message => {
    const source = typeof message.source === 'object' && message.source !== null
      ? message.source as Record<string, unknown> : undefined
    const replay = message.role === 'assistant'
      && source?.['kind'] === 'model' && source['provider'] === request.provider && source['model'] === request.model
      ? replayOutput(source['replayState'], message.content, context) : undefined
    const replayState = source?.['replayState'] as { response?: { reasoningReplay?: unknown, reasoningUpdatesUnsupported?: unknown } } | undefined
    const reasoningReplay = replay === undefined ? undefined : readReasoningReplay(replayState?.response?.reasoningReplay)
    const content: InputPart[] = []
    for (const block of message.content) {
      if (block.type === 'text' && typeof block['text'] === 'string') {
        content.push({ type: 'text', text: block['text'] })
      } else if (block.type === 'image' && typeof block['url'] === 'string') {
        content.push({ type: 'image', url: block['url'] })
      } else if (block.type === 'tool-call') {
        const call = block as { id: string, name: string, arguments: string }
        content.push({ type: 'tool-call', id: call.id, name: call.name, arguments: call.arguments })
      }
      // Old/foreign reasoning summaries are for display, not a replacement for
      // opaque provider reasoning. Missing native state cannot be reconstructed.
    }
    return {
      role: message.role, content,
      ...message.toolCallId === undefined ? {} : { toolCallId: message.toolCallId },
      ...message.isError === undefined ? {} : { isError: message.isError },
      ...replay === undefined ? {} : { replay },
      ...reasoningReplay === undefined ? {} : { reasoningReplay },
      ...replay !== undefined && replayState?.response?.reasoningUpdatesUnsupported === true
        ? { reasoningUpdatesUnsupported: true as const } : {},
    }
  })
  const cacheKey = scope === undefined ? undefined
    : sessionCacheKey(scope, request.provider, request.sessionId, request.purpose)
  return {
    model: request.model, messages,
    ...request.system === undefined ? {} : { system: request.system },
    ...request.tools?.length ? { tools: request.tools } : {},
    ...request.reasoningEffort === undefined ? {} : { reasoningEffort: request.reasoningEffort },
    ...cacheKey === undefined ? {} : { cacheKey },
  }
}

/**
 * Run one authenticated call, renewing the grant once if the endpoint refuses it.
 *
 * A stored token can be refused while it still looks valid locally: the endpoint
 * answers `token_expired` for a grant it invalidated server-side, and authorization
 * can change under a live session — an account upgrade, a workspace switch. A
 * local clock comparison cannot see either, so the endpoint's refusal is what
 * triggers a renewal, and the call is attempted twice at most.
 *
 * @param usable - mints a token from the stored grant, refreshing if it looks stale.
 * @param renew - exchanges the grant for a new one regardless of local expiry.
 * @param call - the authenticated call, given a token.
 * @returns what the call produced.
 * @throws the second attempt's failure, or the first one when a renewal was not the answer.
 */
async function withFreshGrant<T>(
  usable: () => Promise<ChatGptCredential>,
  renew: (stale: ChatGptCredential) => Promise<ChatGptCredential>,
  call: (credential: ChatGptCredential) => Promise<T>,
): Promise<T> {
  const credential = await usable()
  try {
    return await call(credential)
  } catch (error) {
    // Only an authentication refusal is worth a renewal; anything else would
    // spend a refresh token to be told the same thing again.
    if (!isCodedError(error) || (error.status !== 401
      && !(error.status === 403 && (error.code === 'token_expired' || error.code === 'invalid_token')))) throw error
    const renewed = await renew(credential)
    return await call(renewed)
  }
}

/**
 * Classify a failure from getting a usable credential.
 *
 * "Not signed in" is one specific condition — this installation has no account, or
 * its grant was refused for good — and it must not be reported for a dropped
 * connection. Reporting a network blip as a missing credential sends the human to
 * sign in again over something a retry repairs, so a transport failure carries the
 * code the retry policy acts on instead.
 *
 * @param auth - the credential owner, asked whether any account is stored.
 * @param error - whatever the credential step or the first read threw.
 * @returns the coded failure to report.
 */
function credentialFailure(auth: ChatGptAuth, error: unknown): CodedError {
  const message = error instanceof Error ? error.message : String(error)
  if (auth.active() === undefined) {
    // `usable()` already says exactly this, so wrapping it would say it twice.
    return coded(message, 'chatgpt_not_signed_in')
  }
  if (error instanceof RefreshRefusedError) {
    return error.terminal
      ? coded(`the ChatGPT grant was refused and needs a new sign-in: ${message}`, 'chatgpt_not_signed_in')
      : coded(`the ChatGPT grant could not be renewed right now: ${message}`, 'TRANSPORT')
  }
  return isTransportFailure(message)
    ? coded(`the ChatGPT request could not reach the service: ${message}`, 'TRANSPORT')
    : coded(`the ChatGPT request could not be prepared: ${message}`, 'chatgpt_request_failed')
}

/**
 * A failure this plugin itself decided on, in the coded shape its layers share.
 *
 * `ApiError` normalizes the codes it carries for endpoint-failure taxonomy, so a
 * plugin-level refusal that must keep its exact code travels in this shape
 * instead — the host boundary passes a coded error through unchanged.
 *
 * @param message - what the human reads.
 * @param code - the stable machine code, kept verbatim.
 * @returns the coded error to throw.
 */
function pluginCodedError(message: string, code: string): CodedError {
  const error = new Error(message)
  Object.assign(error, { code })
  return error as CodedError
}

/**
 * Map a thrown credential/listing error to the failure the harness sees.
 *
 * `RefreshRefusedError` carries a `code` of its own (`CHATGPT_REFRESH_REFUSED`),
 * so a generic coded-error passthrough would let it escape before
 * {@link credentialFailure} can translate a dead grant into
 * `chatgpt_not_signed_in`. Genuine API refusals keep their own code.
 *
 * @param auth - the credential owner, asked whether any account is stored.
 * @param error - whatever the credential step or the first read threw.
 * @returns the coded failure to report.
 */
function codedCredentialFailure(auth: ChatGptAuth, error: unknown): CodedError {
  if (isCodedError(error) && error.code === 'stream_ended_early') {
    return Object.assign(new Error(error.message, { cause: error }), { code: 'TRANSPORT' })
  }
  if (error instanceof RefreshRefusedError) return credentialFailure(auth, error)
  return isCodedError(error) ? error : credentialFailure(auth, error)
}

/** Describe a model and its selected compaction budget in the host's vocabulary. */
function toHarnessResolved(
  provider: string, model: DescribedModel, contextWindow: number,
): HarnessResolvedModel {
  return {
    provider,
    id: model.id,
    name: model.name,
    inputModalities: model.input,
    // Let DSH compact against this budget; the adapter never truncates history.
    context: { contextWindow },
    systemPromptUpdate: 'in-history',
    ...model.maxTokens === undefined ? {} : { defaultMaxTokens: Math.min(model.maxTokens, Math.floor(contextWindow / 2)) },
    ...model.reasoningEfforts === undefined ? {} : {
      reasoning: {
        efforts: model.reasoningEfforts,
        ...model.defaultReasoningEffort === undefined ? {} : { defaultEffort: model.defaultReasoningEffort },
      },
    },
  }
}

/**
 * Serves one harness provider route from a ChatGPT plan.
 *
 * The route name is supplied by the composition rather than fixed here, so the
 * same adapter can serve a private route alongside the built-in provider or
 * replace its name, without this module deciding.
 */
export class ChatGptAdapter {
  private readonly auth: ChatGptAuth
  private readonly baseUrl: string | undefined
  private readonly displayName: string
  private readonly includeUnlisted: boolean
  private readonly contextWindowLimit: ChatGptAdapterOptions['contextWindowLimit']
  private readonly modelContextWindowLimits: ChatGptAdapterOptions['modelContextWindowLimits']
  private readonly streamIdleTimeoutMs: ChatGptAdapterOptions['streamIdleTimeoutMs']
  private readonly now: () => number
  private readonly onListingRecovered: (() => void) | undefined
  private readonly stateDir: string | undefined
  private readonly onModelSwitchesChanged: (() => void) | undefined
  private listingGeneration = 0
  private listing: { namespace: string | undefined, at: number, models: DescribedModel[] } | undefined
  /** Whether the most recent listing attempt failed, so the next success can announce it. */
  private listingFailed = false

  /**
   * @param options - the credential owner and endpoint policy.
   */
  constructor(options: ChatGptAdapterOptions) {
    this.auth = options.auth
    this.baseUrl = options.baseUrl
    this.displayName = options.displayName ?? 'ChatGPT'
    this.includeUnlisted = options.includeUnlisted ?? true
    this.contextWindowLimit = options.contextWindowLimit
    this.modelContextWindowLimits = options.modelContextWindowLimits
    this.streamIdleTimeoutMs = options.streamIdleTimeoutMs
    this.now = options.now ?? (() => Date.now())
    this.onListingRecovered = options.onListingRecovered
    this.stateDir = options.stateDir
    this.onModelSwitchesChanged = options.onModelSwitchesChanged
  }

  /** The provider row this adapter describes. */
  providerInfo(provider: string): { id: string, name: string } {
    return { id: provider, name: this.displayName }
  }

  /**
   * The models the selector should offer, in the server's order.
   *
   * The roster this account produced, minus the models the human switched off,
   * with each hand-set display name applied. A switched-off model is hidden
   * from the offering only: a request that names it directly still reaches the
   * endpoint and gets its own answer, exactly as the roster itself has never
   * been an allowlist. A renamed model keeps its id — the name is what the
   * picker shows, never what a request carries.
   *
   * @returns the describable, switched-on models under their display names.
   */
  async listModels(): Promise<readonly DescribedModel[]> {
    const [models, overrides] = await Promise.all([this.rosterModels(), this.modelOverrides()])
    const offered = overrides.disabled.size === 0
      ? models
      : models.filter(model => !overrides.disabled.has(model.id))
    return offered.map(model => ({
      ...model,
      name: overrides.names.get(model.id) ?? model.name,
      contextWindow: overrides.contextWindows.get(model.id) ?? this.configuredContextWindow(model.id),
    }))
  }

  /**
   * Every roster model with its switch and display-name state, for the provider
   * card.
   *
   * The roster is the same one the selector's offering comes from, so a switch
   * list and a selector can never disagree about what exists — only about which
   * entries are offered and what each is called.
   *
   * @returns one row per roster model, roster order.
   */
  async modelSwitches(): Promise<readonly ModelSwitchView[]> {
    const [models, overrides] = await Promise.all([this.rosterModels(), this.modelOverrides()])
    return models.map((model) => {
      const name = overrides.names.get(model.id)
      return {
        id: model.id,
        defaultName: model.name,
        name: name ?? model.name,
        disabled: overrides.disabled.has(model.id),
        contextWindow: overrides.contextWindows.get(model.id) ?? this.configuredContextWindow(model.id),
        defaultContextWindow: this.configuredContextWindow(model.id),
      }
    })
  }

  /**
   * Switch one roster model on or off and answer the resulting switch list.
   *
   * @param id - the exact model id, which must be on the current roster.
   * @param disabled - whether the selector should stop offering the model.
   * @returns the switch list after the change is persisted.
   * @throws {CodedError} `chatgpt_unknown_model` when the id is not on the
   * roster, so a stale card cannot switch a model the account no longer serves.
   */
  async setModelDisabled(id: string, disabled: boolean): Promise<readonly ModelSwitchView[]> {
    return this.changeModels(() => this.setModelDisabledUnlocked(id, disabled))
  }

  private async setModelDisabledUnlocked(id: string, disabled: boolean): Promise<readonly ModelSwitchView[]> {
    await this.requireSwitchable(id)
    const overrides = await this.storedOverrides()
    if (disabled) overrides.disabled.add(id)
    else overrides.disabled.delete(id)
    return await this.commitOverrides(overrides)
  }

  /**
   * Set one roster model's display name, or restore the roster's own.
   *
   * The name is display vocabulary only: the selector shows it, while requests
   * keep carrying the id, so a rename can never break a call the way a renamed
   * allowlist entry would.
   *
   * @param id - the exact model id, which must be on the current roster.
   * @param name - the display name to store; `undefined` or blank restores the
   * roster's own name by removing the override.
   * @returns the switch list after the change is persisted.
   * @throws {CodedError} `chatgpt_unknown_model` when the id is not on the
   * roster, `chatgpt_invalid_model_switch` when the name is longer than the
   * accepted bound.
   */
  async setModelName(id: string, name: string | undefined): Promise<readonly ModelSwitchView[]> {
    return this.changeModels(() => this.setModelNameUnlocked(id, name))
  }

  private async setModelNameUnlocked(id: string, name: string | undefined): Promise<readonly ModelSwitchView[]> {
    await this.requireSwitchable(id)
    const trimmed = name?.trim() ?? ''
    if (trimmed.length > MAX_MODEL_NAME_LENGTH) {
      throw pluginCodedError(
        `a model display name is limited to ${String(MAX_MODEL_NAME_LENGTH)} characters`,
        'chatgpt_invalid_model_switch',
      )
    }
    const overrides = await this.storedOverrides()
    if (trimmed.length === 0) overrides.names.delete(id)
    else overrides.names.set(id, trimmed)
    return await this.commitOverrides(overrides)
  }

  /** Persist one fixed context choice and notify the host to resolve the model again. */
  async setModelContextWindow(id: string, contextWindow: number): Promise<readonly ModelSwitchView[]> {
    return this.changeModels(async () => {
      await this.requireSwitchable(id)
      if (!isContextWindow(contextWindow)) {
        throw pluginCodedError('context window must be 1M, 800k, 500k or 300k', 'chatgpt_invalid_model_switch')
      }
      const overrides = await this.storedOverrides()
      overrides.contextWindows.set(id, contextWindow)
      return this.commitOverrides(overrides)
    })
  }

  /**
   * Clear model switches, display names and context choices.
   *
   * @returns the switch list after the reset is persisted.
   * @throws {CodedError} `chatgpt_switches_unavailable` when no state directory
   * is configured, since the reset could not be remembered.
   */
  async resetModels(): Promise<readonly ModelSwitchView[]> {
    return this.changeModels(() => this.resetModelsUnlocked())
  }

  private async resetModelsUnlocked(): Promise<readonly ModelSwitchView[]> {
    if (this.stateDir === undefined) {
      throw pluginCodedError('model switches need the installation state directory', 'chatgpt_switches_unavailable')
    }
    const overrides = await this.storedOverrides()
    if (overrides.disabled.size === 0 && overrides.names.size === 0 && overrides.contextWindows.size === 0) {
      return await this.modelSwitches()
    }
    overrides.disabled.clear()
    overrides.names.clear()
    overrides.contextWindows.clear()
    return await this.commitOverrides(overrides)
  }

  /**
   * The gates every override write shares: a place to persist, and a model the
   * roster actually carries.
   *
   * @param id - the exact model id a stale card may have named.
   * @throws {CodedError} `chatgpt_switches_unavailable`, then
   * `chatgpt_invalid_model_switch`, then `chatgpt_unknown_model`.
   */
  private async requireSwitchable(id: string): Promise<void> {
    if (this.stateDir === undefined) {
      throw pluginCodedError('model switches need the installation state directory', 'chatgpt_switches_unavailable')
    }
    if (id.length === 0) {
      throw pluginCodedError('a model id is required', 'chatgpt_invalid_model_switch')
    }
    const roster = await this.rosterModels()
    if (!roster.some(model => model.id === id)) {
      throw pluginCodedError(`the roster has no model ${id}`, 'chatgpt_unknown_model')
    }
  }

  private async changeModels(task: () => Promise<readonly ModelSwitchView[]>): Promise<readonly ModelSwitchView[]> {
    if (this.stateDir === undefined) throw pluginCodedError('model switches need the installation state directory', 'chatgpt_switches_unavailable')
    await mkdir(this.stateDir, { recursive: true, mode: 0o700 })
    return withCredentialFileLock(join(this.stateDir, 'models-operation'), task)
  }

  /** The persisted overrides as a mutable working copy. */
  private async storedOverrides(): Promise<{ disabled: Set<string>, names: Map<string, string>, contextWindows: Map<string, ContextWindow> }> {
    const file = this.stateDir === undefined
      ? { disabled: [] as readonly string[], names: {} as Readonly<Record<string, string>> }
      : await readModelOverrides(this.stateDir)
    return { disabled: new Set(file.disabled), names: new Map(Object.entries(file.names)),
      contextWindows: new Map(Object.entries(file.contextWindows ?? {})) }
  }

  /**
   * Persist the working copy, announce it, and answer the fresh switch list.
   * @param overrides - the overrides to store.
   * @returns the switch list as the persisted state now reads.
   */
  private async commitOverrides(
    overrides: { disabled: ReadonlySet<string>, names: ReadonlyMap<string, string>, contextWindows: ReadonlyMap<string, ContextWindow> },
  ): Promise<readonly ModelSwitchView[]> {
    const stateDir = this.stateDir
    if (stateDir === undefined) {
      throw pluginCodedError('model switches need the installation state directory', 'chatgpt_switches_unavailable')
    }
    const file: ModelOverridesFile = {
      disabled: [...overrides.disabled],
      names: Object.fromEntries(overrides.names),
      ...overrides.contextWindows.size === 0 ? {} : { contextWindows: Object.fromEntries(overrides.contextWindows) },
    }
    await writeModelOverrides(stateDir, file)
    // The listing cache is the unfiltered roster, so nothing here invalidates
    // it; the selector rebuilds its offering because the Host is told it changed.
    try {
      this.onModelSwitchesChanged?.()
    } catch {
      // The overrides are already persisted; a listener failure cannot undo it.
    }
    return await this.modelSwitches()
  }

  /**
   * The models this account advertises, in the server's order.
   *
   * This is a *roster for display*, not an allowlist. The endpoint lists what it
   * wants a picker to show, and it serves models that are absent from that list:
   * asked directly, it answers under the requested id and reports having done so.
   * Gating a call on membership here would refuse models the account can really
   * use — a mistake this plugin made once and should not make again.
   *
   * What the harness offers is therefore the roster; what a call may reach is
   * whatever the endpoint accepts, and its own error is the answer for a model
   * that does not exist.
   *
   * An account that is not signed in has no roster, which is an empty catalog
   * rather than a failure: the route exists and is waiting for a sign-in.
   *
   * @returns the describable models, before any switches are applied.
   */
  private async rosterModels(): Promise<readonly DescribedModel[]> {
    const namespace = this.auth.active()?.replayNamespace
    const generation = this.listingGeneration
    const cached = this.listing
    if (cached !== undefined && cached.namespace === namespace && this.auth.active() !== undefined
      && this.now() - cached.at < LISTING_TTL_MS) return cached.models
    // No account is an empty roster, not a failure: the route exists and is
    // waiting for a sign-in, and a throwing listing would make the selector
    // unusable before the first one.
    if (this.auth.active() === undefined) return []
    let listed: ListedModel[]
    try {
      listed = await withFreshGrant(
        () => this.auth.usable(),
        credential => this.auth.renewFor(credential),
        credential => listModels(credential.accessToken, ...this.baseUrl === undefined ? [] : [{ baseUrl: this.baseUrl }]),
      )
    } catch (error) {
      if (generation !== this.listingGeneration || this.auth.active()?.replayNamespace !== namespace) return []
      this.listingFailed = true
      // Listing shares the credential rules with a turn: a refused refresh is a
      // dead grant, not a listing the human can retry. Mapping it through
      // `credentialFailure` keeps the code (`chatgpt_not_signed_in`) that lets the
      // card stop claiming a dead grant is still signed in.
      throw codedCredentialFailure(this.auth, error)
    }
    if (generation !== this.listingGeneration || this.auth.active()?.replayNamespace !== namespace
      || this.auth.active() === undefined) return []
    const models = this.rosterOf(listed)
    this.listing = { namespace, at: this.now(), models }
    if (this.listingFailed) {
      this.listingFailed = false
      // The model selector can cache a provider failure, and its Retry may read
      // that cache instead of asking again. A recovered listing therefore has to
      // announce itself; a listener failure cannot make a good roster unusable.
      try {
        this.onListingRecovered?.()
      } catch {
        // The models are already resolved and cached.
      }
    }
    return models
  }

  /**
   * The roster the selector offers: what the account advertises, plus the models
   * measured to work on this route that the listing leaves out.
   *
   * The listing is a curated selection, not an inventory. It omits models this
   * route serves — asked for by id, they answer — so a roster built from it alone
   * hides models the account paid for. The extra ids come from
   * {@link SERVED_MODELS}, which records when they were measured, because no
   * endpoint states them.
   *
   * A model the listing marks hidden is not offered: hidden is a deliberate
   * instruction about what a picker should show, and it is a different statement
   * from leaving a model unmentioned.
   *
   * @param listed - every entry the account's listing returned.
   * @returns the models to offer, listing order first.
   */
  private rosterOf(listed: readonly ListedModel[]): DescribedModel[] {
    const advertised = describableModels(listed).map(model => this.withMeasurement(model))
    const present = new Set(listed.map(model => model.slug))
    const extras = this.includeUnlisted
      ? SERVED_MODELS
          .filter(entry => !entry.advertised && !present.has(entry.id))
          .map(entry => {
            const described = describeModel({ slug: entry.id })
            // No account default is available. Keep the bundled default and
            // retain the observed route maximum as descriptive metadata only.
            return {
              ...described,
              maxContextWindow: ROUTE_MAX_CONTEXT_WINDOW,
              maxTokens: described.maxTokens ?? ROUTE_MAX_OUTPUT_TOKENS,
              metadataSource: 'measured' as const,
            }
          })
      : []
    return [...advertised, ...extras]
  }

  /**
   * Overlay the measured facts about one model.
   *
   * The listing describes capacity and the endpoint accepts requests, but its
   * reasoning-level list is not reliable — it advertised a level the API refuses.
   * Where a measurement exists it wins, because the cost of offering a rejected
   * level is a failed turn.
   */
  private withMeasurement(model: DescribedModel): DescribedModel {
    const record = servedRecord(model.id)
    if (record === undefined) return model
    const efforts = record.reasoningEfforts.map(effort => ({ id: effort, name: effortLabel(effort) }))
    // `medium` is the published default wherever the model accepts it, matching
    // what the endpoint reports for the models it describes.
    const preferred = record.reasoningEfforts.includes('medium') ? 'medium' : undefined
    return {
      ...model,
      reasoningEfforts: efforts,
      ...preferred === undefined
        ? model.defaultReasoningEffort === undefined ? {} : { defaultReasoningEffort: model.defaultReasoningEffort }
        : { defaultReasoningEffort: preferred },
    }
  }

  /**
   * The stored roster overrides, or empty when they cannot live anywhere. Read
   * per call rather than cached, so an edit made in one DSH process is seen by
   * the next listing in another.
   */
  private async modelOverrides(): Promise<{ disabled: ReadonlySet<string>, names: ReadonlyMap<string, string>, contextWindows: ReadonlyMap<string, ContextWindow> }> {
    return this.storedOverrides()
  }

  /** Configured budgets remain readable even when absent from the fixed UI choices. */
  private configuredContextWindow(model: string): number {
    const overrides = typeof this.modelContextWindowLimits === 'function'
      ? this.modelContextWindowLimits() : this.modelContextWindowLimits
    if (overrides !== undefined && (overrides === null || typeof overrides !== 'object' || Array.isArray(overrides))) {
      throw new Error('modelContextWindowLimits must be an object keyed by exact model ID')
    }
    const modelLimit = overrides !== undefined && Object.hasOwn(overrides, model) ? overrides[model] : undefined
    const limit = modelLimit !== undefined ? modelLimit
      : typeof this.contextWindowLimit === 'function' ? this.contextWindowLimit() : this.contextWindowLimit
    if (limit !== undefined && (!Number.isSafeInteger(limit) || limit < 1024)) {
      const setting = modelLimit === undefined ? 'contextWindowLimit' : `modelContextWindowLimits[${JSON.stringify(model)}]`
      throw new Error(`${setting} must be a safe integer of at least 1024 tokens`)
    }
    return limit ?? defaultContextWindow(model)
  }

  /** Drop the cached listing, so the next question re-asks the account. */
  forgetListing(): void {
    this.listingGeneration += 1
    this.listing = undefined
  }

  /**
   * Everything known about one model.
   *
   * The listing is consulted first so an account-specific display name wins,
   * and the bundled catalog answers for a model the listing has not been asked
   * about — a direct call must not depend on a listing having happened.
   *
   * @param provider - the route.
   * @param model - the exact model id.
   * @returns the model's metadata.
   */
  async resolveModel(provider: string, model: string): Promise<HarnessResolvedModel> {
    const listed = (await this.rosterModels().catch(() => [])).find(entry => entry.id === model)
    const described = listed ?? describableModels([{ slug: model }])[0]
    /* c8 ignore next -- describableModels always answers for a non-empty slug */
    if (described === undefined) throw new Error(`no model named "${model}"`)
    const overrides = await this.modelOverrides()
    const contextWindow = overrides.contextWindows.get(model) ?? this.configuredContextWindow(model)
    return toHarnessResolved(provider, described, contextWindow)
  }

  /**
   * Stream one turn.
   *
   * A credential that cannot be refreshed is reported as an authentication
   * failure rather than retried, because the recovery is a new sign-in and no
   * amount of retrying produces one.
   *
   * @param provider - the route (unused; one grant serves the account).
   * @param request - the harness request.
   * @returns the chunks for one assistant turn.
   */
  async *stream(provider: string, request: HarnessRequest): AsyncGenerator<AdapterChunk, void, undefined> {
    void provider
    let translator: BlockTranslator
    let events: AsyncGenerator<ResponsesEvent, void, undefined>
    let primed: IteratorResult<ResponsesEvent>
    try {
      ({ events, primed, translator } = await withFreshGrant(
        () => this.auth.usable(request.signal),
        credential => this.auth.renewFor(credential, request.signal),
        // A generator is lazy, so a refused token would not surface until the
        // first read. Reading one step inside the retry is what lets the refusal
        // be answered here, before the caller has seen anything — and the event
        // that read produced is carried out, not discarded.
        async (credential) => {
          const scope = accountScope(this.baseUrl ?? RESOURCE, credential)
          const neutral = toNeutralRequest(request, scope)
          const initialPrepared = prepareResponsesRequest(neutral)
          const start = async (unsupported?: true) => {
            const prepared = unsupported
              ? prepareResponsesRequest({ ...neutral, reasoningUpdatesUnsupported: true }) : initialPrepared
            const translator = new BlockTranslator(scope === undefined ? undefined : {
              provider: request.provider, model: request.model, scope,
              ...prepared.reasoningReplay === undefined ? {} : { reasoningReplay: prepared.reasoningReplay },
              ...prepared.reasoningUpdatesUnsupported === undefined ? {} : { reasoningUpdatesUnsupported: true as const },
            })
            const idleTimeoutMs = typeof this.streamIdleTimeoutMs === 'function'
              ? this.streamIdleTimeoutMs() : this.streamIdleTimeoutMs
            const started = streamTurn({
              accessToken: credential.accessToken,
              request: neutral,
              preparedBody: prepared.body,
              ...idleTimeoutMs === undefined ? {} : { idleTimeoutMs },
              ...this.baseUrl === undefined ? {} : { endpoints: { baseUrl: this.baseUrl } },
              ...request.signal === undefined ? {} : { signal: request.signal },
            })
            return { events: started, primed: await started.next(), translator }
          }
          try {
            return await start()
          } catch (error) {
            // SIWC may reject configuration items that the public API accepts.
            // Retry only a pre-stream capability refusal, then remember it in
            // successful response metadata rather than failing every switch.
            if (!(error instanceof ApiError) || error.code !== 'subscription_sharing_unsupported_capability'
              || !/unsupported input items/i.test(error.message)
              || !initialPrepared.body.input.some(item => item.type === 'configuration_update')) throw error
            return await start(true)
          }
        },
      ))
    } catch (error) {
      if (isCodedError(error) && (error.status === 401 || error.status === 403)) this.forgetListing()
      throw codedCredentialFailure(this.auth, error)
    }
    try {
      for (let step: IteratorResult<ResponsesEvent> = primed; !step.done; step = await events.next()) {
        for (const chunk of translator.push(step.value)) yield chunk
      }
    } catch (error) {
      // A refused grant means this credential is finished; the next request
      // must not reuse it, so the listing is dropped with it.
      if (isCodedError(error) && (error.status === 401 || error.status === 403)) this.forgetListing()
      // Whatever went wrong, the blocks this turn opened still have to close, or
      // the harness holds a block that never ends.
      for (const chunk of translator.endAll()) yield chunk
      // Already coded when it came from the client; otherwise name it here so the
      // host has something better than an unknown failure to report.
      if (isCodedError(error)) throw codedCredentialFailure(this.auth, error)
      const message = error instanceof Error ? error.message : String(error)
      // A stream cut short is retryable, and the harness retries exactly the codes
      // its policy names; anything else keeps the honest protocol-error code.
      throw isTransportFailure(message)
        ? coded(`the ChatGPT response was cut short: ${message}`, 'TRANSPORT')
        : coded(message, 'chatgpt_request_failed')
    } finally {
      await events.return(undefined)
    }
  }
}
